tools.post_process_code:
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            left = d.get('wrong_answers_left')
            if d.get('all_verified') is True:
                d['what_to_do_next'] = 'Identity verified.'
            elif d.get('hint') == 'day_month_swapped':
                d['what_to_do_next'] = 'Ask the customer to say the date of birth again. Do not swap it yourself.'
            elif d.get('verified') is True:
                d['what_to_do_next'] = 'Correct. Ask the next security question.'
            elif d.get('verified') is False and left == 0:
                d['what_to_do_next'] = 'Three wrong answers. Say: Please use the app or visit a branch. Then say goodbye, ending with Have a good day.'
            elif d.get('verified') is False:
                d['what_to_do_next'] = 'Wrong answer. Ask the same question again.'
            elif d.get('ok') is False:
                d['what_to_do_next'] = 'The answer could not be read and was not counted. Ask for it again.'
except Exception:
    pass

try:
    from decimal import Decimal, ROUND_HALF_UP
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            if d.get('ok') is False:
                d['what_to_do_next'] = 'The account could not be loaded. Call get_account once more.'
            for p in (d.get('products') or []):
                if not isinstance(p, dict):
                    continue
                due = Decimal(str(p.get('past_due')))
                p['floor_30_percent'] = str((due * Decimal('0.3')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
                if int(p.get('days_late') or 0) <= 10:
                    p['band'] = 'early'
                    p['attempts'] = 1
                    p['latest_promise_date'] = '2026-10-21 (Wednesday)'
                else:
                    p['band'] = 'late'
                    p['attempts'] = 2
                    p['latest_promise_date'] = '2026-10-15 (Thursday)'
except Exception:
    pass

try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and d.get('ok') is True:
            d['what_to_do_next'] = 'Saved. Say: A confirmation email will be sent to the address on file. Then say goodbye, ending with Have a good day.'
        elif isinstance(d, dict):
            d['what_to_do_next'] = 'Not saved. Call create_promise once more with the same amount and date. Do not say it is saved.'
except Exception:
    pass

